import { lazy } from 'react';
import { GanttChart as IcGanttChart, GitBranch as IcGitBranch, KanbanSquare as IcKanbanSquare, Table2 as IcTable2, Wrench as IcWrench } from 'lucide-react';
import { TabHub } from '@/components/pulse-ui';

/**
 * Boards & Schedule — hub page for the Projects menu.
 *
 * Generated by the 2026-09-16 information-architecture pass, which collapsed
 * 5 sidebar rows into this one destination. Each page below keeps its
 * NAV_ITEMS entry marked `inHub: 'ProjectBoards'`, so getSectionForPage() still
 * resolves it and every role gate behaves exactly as it did when each was its
 * own row. TabHub re-checks each tab with canRoleOpenPage() before drawing it.
 */
const ProductionDeliveryTracker = lazy(() => import('./ProductionDeliveryTracker'));
const ProjectPipelineBoard = lazy(() => import('./ProjectPipelineBoard'));
const KanbanBoard = lazy(() => import('./KanbanBoard'));
const GanttChart = lazy(() => import('./GanttChart'));
const InstallationDashboard = lazy(() => import('./InstallationDashboard'));

export const TABS = [
  { id: 'master', label: 'Project Master', icon: IcTable2, page: 'ProductionDeliveryTracker', Component: ProductionDeliveryTracker },
  { id: 'pipeline', label: 'Project Pipeline', icon: IcGitBranch, page: 'ProjectPipelineBoard', Component: ProjectPipelineBoard },
  { id: 'tasks', label: 'Task Board', icon: IcKanbanSquare, page: 'KanbanBoard', Component: KanbanBoard },
  { id: 'gantt', label: 'Gantt Chart', icon: IcGanttChart, page: 'GanttChart', Component: GanttChart },
  { id: 'install', label: 'Installation', icon: IcWrench, page: 'InstallationDashboard', Component: InstallationDashboard },
];

export default function ProjectBoards({ setPage }) {
  return (
    <TabHub
      icon={IcKanbanSquare}
      eyebrow="Projects"
      title="Boards & Schedule"
      subtitle="The IPP delivery grid, the stage pipeline, task kanban, the Gantt schedule and installation"
      tabs={TABS}
      setPage={setPage}
    />
  );
}
